-- ES/DE/FR translations for all 10 Sweden milestones.
-- se-b2g and se-b2b-expected reuse the tracker's own phrasing per
-- tracker-phrasing-wins.

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-b2g-2008', 'es', 'Primer mandato parcial B2G — organismos del gobierno central', 'Todas las facturas enviadas a las administraciones públicas centrales deben ser electrónicas, junto con la creación de las funciones predecesoras de DIGG para orientar la digitalización del sector público.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-b2g-2008', 'de', 'Erste teilweise B2G-Pflicht — zentrale Regierungsbehörden', 'Alle an zentrale öffentliche Verwaltungen gesendeten Rechnungen müssen elektronisch sein, zusammen mit der Schaffung der Vorläuferfunktionen von DIGG zur Steuerung der Digitalisierung des öffentlichen Sektors.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-b2g-2008', 'fr', 'Première obligation B2G partielle — administrations centrales', 'Toutes les factures envoyées aux administrations publiques centrales doivent être électroniques, parallèlement à la création des fonctions précurseurs de DIGG chargées de piloter la numérisation du secteur public.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-act-2018', 'es', 'Ley sobre Facturación Electrónica en la Contratación Pública (Ley 2018:1277)', 'Traspone la Directiva de la UE 2014/55/UE al derecho sueco, estableciendo la base legal para el mandato completo del sector público que sigue.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-act-2018', 'de', 'Gesetz über elektronische Rechnungsstellung im öffentlichen Beschaffungswesen (Gesetz 2018:1277)', 'Setzt die EU-Richtlinie 2014/55/EU in schwedisches Recht um und schafft die rechtliche Grundlage für die anschließende vollständige Pflicht im öffentlichen Sektor.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-act-2018', 'fr', 'Loi sur la facturation électronique dans les marchés publics (loi 2018:1277)', 'Transpose la directive européenne 2014/55/UE en droit suédois, posant le fondement juridique de l''obligation complète du secteur public qui suit.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-b2g', 'es', 'Facturación electrónica B2G obligatoria para todas las entidades públicas (en vigor desde 2019)', 'Todas las autoridades contratantes y entidades públicas de Suecia deben poder recibir facturas electrónicas conformes con la norma EN 16931, siendo Peppol BIS Billing 3.0 el formato recomendado (y cada vez más exigido) a medida que se eliminan formatos heredados como Svefaktura.', '["Proveedores de entidades públicas suecas: utilicen Peppol BIS Billing 3.0 siempre que sea posible — los formatos heredados SFTI/EDIFACT se están retirando", "Todavía no existe un mandato nacional B2B — vea la entrada siguiente sobre la alineación prevista con la UE"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-b2g', 'de', 'B2G-E-Rechnung für alle öffentlichen Stellen verpflichtend (seit 2019 in Kraft)', 'Alle öffentlichen Auftraggeber und öffentlichen Stellen in Schweden müssen in der Lage sein, EN-16931-konforme E-Rechnungen zu empfangen, wobei Peppol BIS Billing 3.0 das empfohlene (und zunehmend geforderte) Format ist, da veraltete Formate wie Svefaktura ausgemustert werden.', '["Lieferanten schwedischer öffentlicher Stellen: verwenden Sie nach Möglichkeit Peppol BIS Billing 3.0 — veraltete SFTI-/EDIFACT-Formate werden abgeschafft", "Es besteht noch keine inländische B2B-Pflicht — siehe den Eintrag unten zur erwarteten EU-Angleichung"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-b2g', 'fr', 'Facturation électronique B2G obligatoire pour toutes les entités publiques (en vigueur depuis 2019)', 'Tous les pouvoirs adjudicateurs et entités publiques en Suède doivent pouvoir recevoir des factures électroniques conformes à la norme EN 16931, Peppol BIS Billing 3.0 étant le format recommandé (et de plus en plus exigé) à mesure que les formats hérités comme Svefaktura sont abandonnés.', '["Fournisseurs des entités publiques suédoises : utilisez Peppol BIS Billing 3.0 dans la mesure du possible — les formats hérités SFTI/EDIFACT sont progressivement retirés", "Aucune obligation nationale B2B n''existe encore — voir l''entrée ci-dessous sur l''alignement attendu avec l''UE"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-b2g-extended-2019', 'es', 'Extendido a todas las administraciones regionales y municipales', 'Se logra la cobertura completa del sector público — toda entidad que desee comerciar con las autoridades públicas debe estar conectada a la red Peppol.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-b2g-extended-2019', 'de', 'Auf alle regionalen und kommunalen Verwaltungen ausgeweitet', 'Vollständige Abdeckung des öffentlichen Sektors erreicht — jede Einrichtung, die mit Behörden handeln möchte, muss an das Peppol-Netzwerk angeschlossen sein.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-b2g-extended-2019', 'fr', 'Étendu à toutes les administrations régionales et municipales', 'Couverture complète du secteur public atteinte — toute entité souhaitant commercer avec les autorités publiques doit être connectée au réseau Peppol.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-b2b-assessment-2023', 'es', 'DIGG, Skatteverket y Bolagsverket solicitan conjuntamente una evaluación B2B/G2B', 'Los tres organismos piden formalmente al gobierno que evalúe la introducción de un mandato nacional de facturación electrónica B2B y G2B — el primer impulso institucional concreto más allá del enfoque voluntario existente.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-b2b-assessment-2023', 'de', 'DIGG, Skatteverket und Bolagsverket fordern gemeinsam eine B2B-/G2B-Bewertung an', 'Die drei Behörden bitten die Regierung formell, die Einführung einer inländischen B2B- und G2B-E-Rechnungspflicht zu prüfen — der erste konkrete institutionelle Vorstoß über den bestehenden freiwilligen Ansatz hinaus.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-b2b-assessment-2023', 'fr', 'DIGG, Skatteverket et Bolagsverket demandent conjointement une évaluation B2B/G2B', 'Les trois organismes demandent formellement au gouvernement d''évaluer l''introduction d''une obligation nationale de facturation électronique B2B et G2B — la première impulsion institutionnelle concrète au-delà de l''approche volontaire existante.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-tullverket-2025', 'es', 'Tullverket (Aduanas suecas) adopta Peppol BIS Billing 3', 'La autoridad aduanera sueca comienza a utilizar Peppol BIS para facturar derechos de aduana, impuestos y tasas — una señal de la continua expansión del formato incluso sin un mandato legal general.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-tullverket-2025', 'de', 'Tullverket (schwedischer Zoll) führt Peppol BIS Billing 3 ein', 'Die schwedische Zollbehörde beginnt, Peppol BIS für die Rechnungsstellung von Zöllen, Steuern und Gebühren zu nutzen — ein Zeichen für die anhaltende Verbreitung des Formats auch ohne allgemeine gesetzliche Pflicht.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-tullverket-2025', 'fr', 'Tullverket (douanes suédoises) adopte Peppol BIS Billing 3', 'L''administration douanière suédoise commence à utiliser Peppol BIS pour facturer les droits de douane, taxes et redevances — un signe de la diffusion continue du format même sans obligation légale générale.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-sfti-phaseout-2025', 'es', 'SFTI elimina progresivamente los formatos heredados como estándares "recomendados"', 'Svefaktura y SFTI ESAP 6 Fulltextfaktura dejan de recomendarse para nuevos proyectos de contratación pública — Peppol BIS pasa a ser el formato preferido, aunque los formatos heredados siguen siendo técnicamente aceptados por ahora.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-sfti-phaseout-2025', 'de', 'SFTI stuft veraltete Formate als "empfohlene" Standards zurück', 'Svefaktura und SFTI ESAP 6 Fulltextfaktura werden für neue öffentliche Beschaffungsprojekte nicht mehr empfohlen — Peppol BIS wird zum bevorzugten Format, obwohl veraltete Formate vorerst technisch weiterhin akzeptiert werden.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-sfti-phaseout-2025', 'fr', 'SFTI retire progressivement les formats hérités des normes « recommandées »', 'Svefaktura et SFTI ESAP 6 Fulltextfaktura ne sont plus recommandés pour les nouveaux projets de marchés publics — Peppol BIS devient le format privilégié, bien que les formats hérités restent techniquement acceptés pour l''instant.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-vida-inquiry-2026', 'es', 'Se lanza la investigación nacional sobre la implementación del ViDA', 'El Ministerio de Finanzas lanza formalmente una investigación sobre cómo debe implementarse el ViDA en el derecho sueco. Se nombra a un comisionado para examinar los cambios legislativos necesarios, evaluar si debe hacerse obligatoria la facturación electrónica B2B nacional, y considerar cómo podría usar Skatteverket los datos de facturación electrónica para la administración del IVA y la prevención del fraude.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-vida-inquiry-2026', 'de', 'Nationale Untersuchung zur ViDA-Umsetzung gestartet', 'Das Finanzministerium leitet formell eine Untersuchung ein, wie ViDA in schwedisches Recht umgesetzt werden soll. Ein Kommissar wird ernannt, um die notwendigen Gesetzesänderungen zu prüfen, zu bewerten, ob eine inländische B2B-E-Rechnungspflicht eingeführt werden soll, und zu untersuchen, wie Skatteverket E-Rechnungsdaten für die Umsatzsteuerverwaltung und Betrugsbekämpfung nutzen könnte.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-vida-inquiry-2026', 'fr', 'Lancement de l''enquête nationale sur la mise en œuvre de ViDA', 'Le ministère des Finances lance formellement une enquête sur la manière dont ViDA doit être mis en œuvre dans le droit suédois. Un commissaire est nommé pour examiner les modifications législatives nécessaires, évaluer s''il convient de rendre obligatoire la facturation électronique B2B nationale, et étudier comment Skatteverket pourrait utiliser les données de facturation électronique pour l''administration de la TVA et la prévention de la fraude.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-inquiry-findings-2027', 'es', 'Vencen las conclusiones de la investigación', 'Esta es la fecha concreta a vigilar — determinará si Suecia sigue a sus vecinos nórdicos hacia un mandato nacional B2B legislado, o continúa con el actual enfoque voluntario de alta adopción.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-inquiry-findings-2027', 'de', 'Ergebnisse der Untersuchung fällig', 'Dies ist das konkrete Datum, das es zu beobachten gilt — es wird bestimmen, ob Schweden seinen nordischen Nachbarn in eine gesetzlich verankerte inländische B2B-Pflicht folgt oder beim aktuellen freiwilligen Ansatz mit hoher Akzeptanz bleibt.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-inquiry-findings-2027', 'fr', 'Les conclusions de l''enquête sont attendues', 'C''est la date concrète à surveiller — elle déterminera si la Suède suit ses voisins nordiques vers une obligation B2B nationale légiférée, ou poursuit son approche volontaire actuelle à forte adoption.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-b2b-expected', 'es', 'Facturación electrónica B2B transfronteriza esperada bajo el ViDA de la UE', 'Suecia aún no ha legislado un mandato nacional de facturación electrónica B2B; Skatteverket, DIGG y Bolagsverket han pedido al gobierno que evalúe uno, pero el único plazo firme actualmente sobre la mesa es el requisito transfronterizo del ViDA a nivel de la UE.', '["Esté atento a un anuncio de mandato nacional — todavía está pendiente una propuesta gubernamental formal", "Los comerciantes transfronterizos deben seguir planificando la preparación para EN 16931/Peppol antes del plazo de la UE de 2030"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-b2b-expected', 'de', 'Grenzüberschreitende B2B-E-Rechnung unter EU-ViDA erwartet', 'Schweden hat noch keine inländische B2B-E-Rechnungspflicht gesetzlich verankert; Skatteverket, DIGG und Bolagsverket haben die Regierung gebeten, eine solche zu prüfen, aber die einzige feste Frist, die derzeit auf dem Tisch liegt, ist die EU-weite grenzüberschreitende ViDA-Anforderung.', '["Achten Sie auf eine Ankündigung einer inländischen Pflicht — ein formeller Regierungsvorschlag steht noch aus", "Grenzüberschreitend handelnde Unternehmen sollten sich dennoch auf EN 16931/Peppol vor der EU-weiten Frist 2030 vorbereiten"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('se-b2b-expected', 'fr', 'Facturation électronique B2B transfrontalière attendue dans le cadre du ViDA de l''UE', 'La Suède n''a pas encore légiféré sur une obligation nationale de facturation électronique B2B ; Skatteverket, DIGG et Bolagsverket ont demandé au gouvernement d''en évaluer une, mais la seule échéance ferme actuellement à l''étude est l''exigence transfrontalière ViDA à l''échelle de l''UE.', '["Surveillez toute annonce d''obligation nationale — une proposition gouvernementale formelle reste en attente", "Les entreprises pratiquant le commerce transfrontalier devraient tout de même préparer leur conformité EN 16931/Peppol avant l''échéance de l''UE de 2030"]');
